/**
 * Removal is a soft delete so the audit log keeps pointing at a real row.
 * `status` is left as it was: it records what the membership was, and
 * `archivedAt` alone says that it ended.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const db = getDb();
  return db.transaction((tx) => {
    const current = tx.select().from(members)
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .get();
    if (!current) throw new Error(`Member ${memberId} not found in org ${orgId}`);
    assertNotArchived("Member", memberId, toMember(current));

    const patch = archivePatch();
    const row = tx.update(members).set(patch)
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning().get();
    tx.update(issues).set({ assigneeId: null, updatedAt: patch.updatedAt })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.assigneeId, current.userId)))
      .run();
    tx.update(projects).set({ leadId: null, updatedAt: patch.updatedAt })
      .where(and(orgPredicate(projects.orgId, orgId), eq(projects.leadId, current.userId)))
      .run();
    return toMember(row);
  });
}

