  const row = getDb().update(members)
    .set({ ...restorePatch(new Date(joinedAt)), status: "active", role, invitedBy, joinedAt })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning().get();
  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId), liveMemberPredicate(), eq(members.status, "active")))
    .run();
}
